def seed_core_document_definitions(apps, schema_editor):
    Definition = apps.get_model('services', 'DocumentDefinition')
    Template = apps.get_model('services', 'DocumentTemplate')
    for order, (code, name) in enumerate(CORE_DOCUMENTS, start=1):
        definition, _ = Definition.objects.get_or_create(
            code=code,
            defaults={
                'name': name,
                'category': 'core',
                'data_source': 'ticket',
                'core_workflow_binding': code,
                'is_active': True,
                'display_order': order * 10,
            },
        )
        Template.objects.get_or_create(
            definition=definition,
            name='Standard',
            defaults={'description': 'Legacy-compatible standard design.', 'is_default': True, 'is_enabled': True},
        )


